using System.Collections.Generic;

// LinkedList de items del inventario
LinkedList<string> inventario = new LinkedList<string>();

// Agregar al inicio y al final — O(1)
LinkedListNode<string> nodoPrimero = inventario.AddFirst("Espada");
LinkedListNode<string> nodoUltimo = inventario.AddLast("Escudo");
inventario.AddLast("Poción");
// inventario: Espada <-> Escudo <-> Poción

// Insertar ANTES o DESPUÉS de un nodo específico — O(1)
// (si ya tienes la referencia al nodo)
inventario.AddAfter(nodoPrimero, "Amuleto");
// inventario: Espada <-> Amuleto <-> Escudo <-> Poción

// Eliminar un nodo por referencia — O(1)
inventario.Remove(nodoPrimero); // elimina Espada

// Recorrer la lista
foreach (string item in inventario)
{
    Debug.Log(item);
}

// Acceder al primer y último elemento — O(1)
string primero = inventario.First.Value; // Amuleto
string ultimo = inventario.Last.Value;   // Poción

